from databricks.sdk import WorkspaceClient
import urllib.parse

w = WorkspaceClient()

# Use the raw API to publish the table
source_table_name = 'workspace.mlpab6ccd46.transactions30b87b'

# The request body with publish_spec
body = {
    "publish_spec": {
        "online_store": "mlpab6ccd46-online-store",
        "online_table_name": "transactions30b87b_online",
        "publish_mode": "CONTINUOUS"
    }
}

# Try with the unencoded table name
try:
    result = w._api_client.do(
        "POST",
        f"/api/2.0/feature-store/tables/{source_table_name}/publish",
        body=body,
        headers={"Content-Type": "application/json"}
    )
    print(f"Success: {result}")
except Exception as e:
    print(f"Error: {e}")

